#!/usr/bin/env bash
# =============================================================================
# apply_fixes.sh  —  R2 Racing Stack: Apply All Fixes
# =============================================================================
# Run from the repo root (folder containing ws_r2_tg30_race_pkg/).
#
#   cd /path/to/Outdoor-Racing-Rosmaster-R2-with-tilt-lidar-main
#   bash apply_fixes.sh
#
# What this does:
#   - Patches 20+ modified files (launch, config, urdf, rviz, lua)
#   - Adds new scripts: pure_pursuit_twist.py, twist_to_rosmaster.py,
#     record_waypoints_live.py, close_loop.py, waypoint_extractor.py,
#     follow_the_gap.py, steering_modifier.py, waypoint_map_builder.py,
#     racing.rviz, README.md, and support scripts
# =============================================================================
set -e
REPO=$(pwd)
PKG="$REPO/ws_r2_tg30_race_pkg"

if [ ! -d "$PKG/r2_tg30_race" ]; then
  echo "ERROR: Run from the repo root (where ws_r2_tg30_race_pkg/ lives)."
  exit 1
fi
echo "=== Applying fixes to: $PKG ==="

# Helper: decode base64 block into a file
b64write() {
  local dst="$1"; shift
  mkdir -p "$(dirname "$dst")"
  echo "$@" | base64 -d > "$dst"
}

echo "  NEW: r2_tg30_race/README.md"
b64write "$PKG/r2_tg30_race/README.md" ""
echo "  NEW: r2_tg30_race/rviz/racing.rviz"
b64write "$PKG/r2_tg30_race/rviz/racing.rviz" ""
echo "  NEW: r2_tg30_race/scripts/bag_control_recorder.py"
b64write "$PKG/r2_tg30_race/scripts/bag_control_recorder.py" ""
echo "  NEW: r2_tg30_race/scripts/close_loop.py"
b64write "$PKG/r2_tg30_race/scripts/close_loop.py" ""
echo "  NEW: r2_tg30_race/scripts/cmdvel_gate.py"
b64write "$PKG/r2_tg30_race/scripts/cmdvel_gate.py" ""
echo "  NEW: r2_tg30_race/scripts/follow_the_gap.py"
b64write "$PKG/r2_tg30_race/scripts/follow_the_gap.py" ""
echo "  NEW: r2_tg30_race/scripts/joy_deadman.py"
b64write "$PKG/r2_tg30_race/scripts/joy_deadman.py" ""
echo "  NEW: r2_tg30_race/scripts/mode_indicator.py"
b64write "$PKG/r2_tg30_race/scripts/mode_indicator.py" ""
echo "  NEW: r2_tg30_race/scripts/pure_pursuit_twist.py"
b64write "$PKG/r2_tg30_race/scripts/pure_pursuit_twist.py" ""
echo "  NEW: r2_tg30_race/scripts/record_waypoints_live.py"
b64write "$PKG/r2_tg30_race/scripts/record_waypoints_live.py" ""
echo "  NEW: r2_tg30_race/scripts/scan_to_cloud.py"
b64write "$PKG/r2_tg30_race/scripts/scan_to_cloud.py" ""
echo "  NEW: r2_tg30_race/scripts/steering_modifier.py"
b64write "$PKG/r2_tg30_race/scripts/steering_modifier.py" ""
echo "  NEW: r2_tg30_race/scripts/twist_to_ackermann.py"
b64write "$PKG/r2_tg30_race/scripts/twist_to_ackermann.py" ""
echo "  NEW: r2_tg30_race/scripts/twist_to_rosmaster.py"
b64write "$PKG/r2_tg30_race/scripts/twist_to_rosmaster.py" ""
echo "  NEW: r2_tg30_race/scripts/waypoint_extractor.py"
b64write "$PKG/r2_tg30_race/scripts/waypoint_extractor.py" ""
echo "  NEW: r2_tg30_race/scripts/waypoint_map_builder.py"
b64write "$PKG/r2_tg30_race/scripts/waypoint_map_builder.py" ""
echo "  NEW: r2_tg30_race/waypoints/waypoints.yaml"
b64write "$PKG/r2_tg30_race/waypoints/waypoints.yaml" ""

echo ""
echo "Applying patches to modified files..."
patch -p1 --forward -d "$REPO" << 'END_PATCH'
