   DESTINATION ${CATKIN_PACKAGE_BIN_DESTINATION}
 )
 
--- a/ws_r2_tg30_race_pkg/r2_tg30_race/config/follow_the_gap.yaml
+++ b/ws_r2_tg30_race_pkg/r2_tg30_race/config/follow_the_gap.yaml
@@ -1,13 +1,27 @@
-scan_topic: /scan_obstacles
-cmd_topic: /cmd_vel_ftg_raw
-# Sidewalk tuning:
-# react earlier to edge grass / curb returns and steer through the widest
-# remaining center gap instead of waiting until obstacles are very close.
-danger_distance: 1.10
-stop_distance: 0.45
-front_angle_deg: 110.0
-bubble_radius_idx: 14
-gap_threshold: 0.70
-max_speed: 0.40
-min_speed: 0.10
-max_angular_z: 1.60
+# follow_the_gap.yaml
+# FTG receives /scan_obstacles which is the full-360° derived LaserScan from
+# pointcloud_to_laserscan. Because that scan already has curb/grass returns
+# (min_height=0.025 m, max_height=0.28 m), FTG automatically treats sidewalk
+# edges and grass borders as obstacles – no extra configuration needed.
+#
+# Tuning for outdoor sidewalk racing:
+#   danger_distance : start reacting at 1.1 m (gives ~1.5 s at 0.7 m/s)
+#   stop_distance   : hard stop at 0.40 m
+#   front_angle_deg : 120° forward cone for gap selection
+#   bubble_radius_idx: inflate obstacles by ~14 beam widths (≈ robot half-width)
+#   gap_threshold   : minimum gap width to consider navigable (0.70 m)
+
+scan_topic:       /scan_obstacles
+cmd_topic:        /cmd_vel_ftg_raw
+
+danger_distance:   1.10   # m – begin FTG override above this distance
+stop_distance:     0.40   # m – publish zero twist if anything is closer
+
+front_angle_deg:   120.0  # degrees – gap search cone centred on robot heading
+bubble_radius_idx:  14    # beam-index radius around each obstacle point
+
+gap_threshold:     0.70   # m – gaps narrower than this are ignored
+
+max_speed:         0.40   # m/s – cap while FTG is active
+min_speed:         0.10   # m/s – minimum forward speed when a gap is found
+max_angular_z:     1.60   # rad/s
--- a/ws_r2_tg30_race_pkg/r2_tg30_race/config/pointcloud_to_laserscan.yaml
+++ b/ws_r2_tg30_race_pkg/r2_tg30_race/config/pointcloud_to_laserscan.yaml
@@ -1,15 +1,34 @@
-# Slice in base_footprint so height thresholds are relative to ground level.
-target_frame: base_footprint
+# pointcloud_to_laserscan.yaml
+# Converts the tilted-LiDAR PointCloud2 into a 2-D LaserScan that:
+#   1. Suppresses flat-ground returns (min_height > 0)
+#   2. Captures curb faces, grass edges, and low obstacles (max_height 0.28 m)
+#   3. Covers the full 360° so FTG and AMCL both see the sides/rear
+#
+# Height thresholds are in the target_frame (base_footprint = ground plane).
+# At 5° tilt, 0.1649 m mount height:
+#   Ground ring hits at ~1.89 m range → these land at z≈0 in base_footprint
+#   A 0.10 m curb face at 1.30 m range → z ≈ 0.10 m in base_footprint
+#   Grass tufts / edge vegetation → 0.03–0.15 m typical
+# So min_height=0.025 skips true ground while keeping all edge features.
+# max_height=0.28 keeps curb tops, low fencing, and tyre-level obstacles.
+
+target_frame: base_footprint   # height relative to ground plane (correct frame)
 transform_tolerance: 0.08
-# Reject flat ground hits, but keep low curb / grass returns above the ground.
-min_height: 0.02
-max_height: 0.22
-angle_min: -1.5708
-angle_max: 1.5708
-angle_increment: 0.00872665
-scan_time: 0.0667
-range_min: 0.12
-range_max: 12.0
-use_inf: true
+
+# --- height slice (ground plane relative) ---
+min_height:  0.025   # skip flat ground returns; keep any feature >= 2.5 cm tall
+max_height:  0.280   # keep curb tops, grass clumps, low kerbing (≤28 cm)
+
+# --- angular coverage: full 360° so FTG sees lateral/rear threats too ---
+angle_min: -3.14159265
+angle_max:  3.14159265
+angle_increment: 0.00872665   # 0.5° resolution (matches TG30 native output)
+
+scan_time:  0.1429   # 1/7 Hz ≈ TG30 spin rate
+range_min:  0.12
+range_max:  12.0
+
+use_inf:    true
 inf_epsilon: 1.0
+
 concurrency_level: 1
--- a/ws_r2_tg30_race_pkg/r2_tg30_race/config/pure_pursuit.yaml
