+# pure_pursuit.yaml
+# IMU note: Pure pursuit locates the robot via map->base_link TF lookup.
+# The TF chain is: AMCL/Cartographer publishes map->odom; EKF (which fuses
+# wheel odom + IMU via imu_filter_madgwick) publishes odom->base_footprint.
+# Pure pursuit therefore benefits from IMU through the EKF odom, with no
+# direct IMU subscription needed here.
+#
+# BUG FIX: odom_topic is a last-resort fallback only. Primary pose source
+# is TF lookup map->base_link (set by AMCL or Cartographer).
+
 lookahead_distance: 0.65
-base_speed: 0.45
-max_speed: 0.70
-min_speed: 0.18
-max_angular_z: 1.40
-goal_tolerance: 0.30
-path_topic: /race_path
-odom_topic: /odom
-cmd_topic: /cmd_vel_auto_raw
+base_speed:         0.45
