+min_speed:          0.18
+max_angular_z:      1.40
+goal_tolerance:     0.30
+
+path_topic:  /race_path
+odom_topic:  /odom        # FALLBACK only – TF map->base_link is used first
+cmd_topic:   /cmd_vel_auto_raw
