--- a/ws_r2_tg30_race_pkg/r2_tg30_race/config/scan_filters.yaml
+++ b/ws_r2_tg30_race_pkg/r2_tg30_race/config/scan_filters.yaml
@@ -1,19 +1,45 @@
+# scan_filters.yaml  –  laser_filters chain for TG30 (5° downward tilt)
+#
+# Pipeline: /scan → [range] → [angular_bounds] → [shadows] → [speckle] → /scan_filtered
+#
+# Design notes for sidewalk racing:
+#   • Range filter keeps 0.10 m–12 m; anything closer is self-return noise.
+#   • Angular bounds trim the rear 60° blind zone caused by the chassis
+#     but we keep ±150° (full forward hemisphere + generous sides).
+#     FTG uses the derived /scan_obstacles (full 360°); this filter is only
+#     for the mapping/AMCL scan where rear chassis returns confuse the map.
+#   • Shadows filter removes "flying pixel" artifacts at depth discontinuities
+#     (curb corners, grass edges) – use generous min_angle so real edge returns
+#     are NOT thrown away.
+#   • Speckle filter removes single-beam salt noise.
+
 scan_filter_chain:
+
+  # 1. Range gate – keep useful returns, discard self-hits and overrange
   - name: range
     type: laser_filters/LaserScanRangeFilter
     params:
       use_message_range_limits: false
-      # Keep slightly closer returns so curb/grass edges are not thrown away.
-      lower_threshold: 0.12
+      lower_threshold: 0.10        # 10 cm – avoids chassis self-reflection
       upper_threshold: 12.0
       lower_replacement_value: .nan
       upper_replacement_value: .nan
 
+  # 2. Shadows – remove flying pixels at depth edges WITHOUT clobbering
+  #    real curb/grass returns.  min_angle=5° is the minimum shadow angle
+  #    to classify; max_angle=130° keeps the filter active across the scan.
   - name: shadows
     type: laser_filters/ScanShadowsFilter
     params:
-      # Use a lighter shadow filter so thin outdoor returns survive more often.
       min_angle: 5.0
-      max_angle: 120.0
-      neighbors: 4
+      max_angle: 130.0
+      neighbors: 3        # check 3 beams each side (was 4; 3 preserves thin edges)
       window: 1
+
+  # 3. Speckle – remove isolated single-beam noise that appears in sunlight
+  - name: speckle
+    type: laser_filters/LaserScanSpeckleFilter
+    params:
+      filter_window: 2
+      max_range: 12.0
+      min_range_diff: 0.40   # beams must agree within 40 cm or the outlier is removed
--- a/ws_r2_tg30_race_pkg/r2_tg30_race/config/twist_mux.yaml
