+            EKF (robot_localization), URDF/TF publishers, joystick teleop.
+
+    Usage:
+      roslaunch yahboomcar_bringup bringup.launch use_ekf:=true
+
+    The joystick node starts automatically.
+    Left stick = drive/steer.  Teleop commands go to /cmd_vel_teleop
+    so twist_mux can blend them with autonomous commands.
+  -->
+
+  <arg name="use_gui"         default="false"/>
+  <arg name="use_rviz"        default="false"/>
+  <arg name="use_ekf"         default="true"/>
+  <arg name="nav_use_rotvel"  default="false"/>
+  <!-- Set ROBOT_TYPE=R2 in your environment before launching -->
+  <arg name="robot_type"      value="$(env ROBOT_TYPE)"
+       doc="robot_type [X1,X3,X3plus,R2,X7]"/>
+
+  <!-- ── URDF / TF publishers ── -->
+  <param name="robot_description"
+         command="$(find xacro)/xacro --inorder
+             '$(find yahboomcar_description)/urdf/yahboomcar_R2.urdf.xacro'"
+         if="$(eval arg('robot_type') == 'R2')"/>
+
+  <!-- Melodic: joint_state_publisher_gui does not exist; always use
+       joint_state_publisher.  Set use_gui:=false (the default). -->
+  <node name="joint_state_publisher" pkg="joint_state_publisher"
+        type="joint_state_publisher"/>
+  <node name="robot_state_publisher" pkg="robot_state_publisher"
+        type="robot_state_publisher"/>
+
+  <!-- ── Hardware driver ── -->
+  <node pkg="yahboomcar_bringup" type="Mcnamu_driver.py"
+        name="driver_node" required="true" output="screen"
+        if="$(eval arg('robot_type') == 'R2')">
+    <param name="car_type"             type="string" value="$(eval arg('robot_type'))"/>
+    <param name="xlinear_speed_limit"  type="double" value="1.0"/>
+    <param name="ylinear_speed_limit"  type="double" value="1.0"/>
+    <param name="angular_speed_limit"  type="double" value="5.0"/>
+    <param name="nav_use_rotvel"       type="bool"   value="$(arg nav_use_rotvel)"/>
+    <param name="imu_link"             type="string" value="imu_link"/>
+    <remap from="/pub_vel" to="/vel_raw"/>
+    <remap from="/pub_imu" to="/imu/imu_raw"/>
+    <remap from="/pub_mag" to="/mag/mag_raw"/>
+  </node>
+
+  <!-- Wrong robot type guard -->
+  <node pkg="yahboomcar_bringup" type="warning.py" name="warning"
+        required="true" output="screen"
+        unless="$(eval arg('robot_type') == 'R2')"/>
+
+  <!-- ── Wheel odometry ── -->
+  <!-- EKF path: publish raw odom; EKF fuses it with IMU → /odom -->
+  <node pkg="yahboomcar_bringup" type="base_node"
+        name="odometry_publisher" output="screen" if="$(arg use_ekf)">
+    <param name="odom_frame"            type="string" value="odom"/>
+    <param name="base_footprint_frame"  type="string" value="base_footprint"/>
+    <param name="linear_scale_x"        type="double" value="1.0"/>
+    <param name="linear_scale_y"        type="double" value="1.0"/>
+    <param name="wheelbase"             type="double" value="0.25"/>
+    <param name="pub_odom_tf"           type="bool"   value="false"/>
+    <remap from="/sub_vel"  to="/vel_raw"/>
+    <remap from="/pub_odom" to="/odom_raw"/>
+  </node>
+
+  <!-- No-EKF path: publish /odom directly and broadcast TF -->
+  <node pkg="yahboomcar_bringup" type="base_node"
+        name="odometry_publisher" output="screen" unless="$(arg use_ekf)">
+    <param name="odom_frame"            type="string" value="odom"/>
+    <param name="base_footprint_frame"  type="string" value="base_footprint"/>
+    <param name="linear_scale_x"        type="double" value="1.0"/>
+    <param name="linear_scale_y"        type="double" value="1.0"/>
+    <param name="wheelbase"             type="double" value="0.25"/>
+    <param name="pub_odom_tf"           type="bool"   value="true"/>
+    <remap from="/sub_vel"  to="/vel_raw"/>
+    <remap from="/pub_odom" to="/odom"/>
+  </node>
+
+  <!-- ── IMU filter (Madgwick) ── -->
+  <node pkg="imu_filter_madgwick" type="imu_filter_node"
+        name="imu_filter_madgwick" output="screen" if="$(arg use_ekf)">
+    <param name="fixed_frame"             value="base_link"/>
+    <param name="use_mag"                 value="false"/>
+    <param name="publish_tf"              value="false"/>
+    <param name="use_magnetic_field_msg"  value="false"/>
+    <param name="world_frame"             value="enu"/>
+    <param name="orientation_stddev"      value="0.05"/>
+    <param name="angular_scale"           value="1.05"/>
+    <remap from="/sub_imu" to="/imu/imu_raw"/>
+    <remap from="/sub_mag" to="/mag/mag_raw"/>
+    <remap from="/pub_imu" to="/imu/imu_data"/>
+    <remap from="/pub_mag" to="/mag/mag_field"/>
+  </node>
+
+  <!-- ── EKF (wheel odom + IMU → /odom) ── -->
+  <node pkg="robot_localization" type="ekf_localization_node"
+        name="ekf_localization" output="screen" if="$(arg use_ekf)">
+    <remap from="odometry/filtered" to="odom"/>
+    <remap from="/imu0"  to="/imu/imu_data"/>
+    <remap from="/odom0" to="odom_raw"/>
+    <param name="odom_frame"       value="/odom"/>
+    <param name="world_frame"      value="/odom"/>
+    <param name="base_link_frame"  value="/base_footprint"/>
+    <rosparam command="load"
+              file="$(find yahboomcar_bringup)/param/robot_localization.yaml"/>
+  </node>
+
+  <!-- ── Joystick teleop ──
+       joy_node reads /dev/input/js0.
+       yahboom_joy converts axes to Twist on /cmd_vel_teleop.
+       twist_mux (started in racing_stack.launch) gives teleop priority 90,
+       so you can always override autonomous commands by moving the stick. -->
+  <include file="$(find yahboomcar_ctrl)/launch/yahboom_joy.launch"/>
+
+  <!-- ── Optional RViz ── -->
+  <node pkg="rviz" type="rviz" name="odom_rviz" required="true"
+        args="-d $(find yahboomcar_bringup)/rviz/odom.rviz"
+        if="$(arg use_rviz)"/>
+
 </launch>
